import { performance, PerformanceObserver } from "node:perf_hooks";
function main(): void {
  console.log(performance.mark("d", { detail: { z: 1 } }).detail);
  const o = new PerformanceObserver((list) => { console.log("obs", list.getEntries().map((e) => e.name)); });
  o.observe({ entryTypes: ["mark"] });
  performance.mark("c");
  setTimeout(() => o.disconnect(), 20);
}
